function evidenzia(nodi, archi) {
  tuttiNodi.forEach(l => nodiEl[l].classList.toggle("spento", nodi && !nodi.has(l)));
  archiEl.forEach(a => { const on = archi && a.ids.some(i => archi.has(i)); a.g.classList.toggle("acceso", !!on); a.g.classList.toggle("spento", !!archi && !on); });
  Object.entries(righeEl).forEach(([i, tr]) => tr.classList.toggle("acceso", !!archi && archi.has(+i)));
}
function listaRel(rs, l) {
  if (!rs.length) return `<p class="vuoto">${TT("Nessuna.", "None.")}</p>`;
  return '<ul class="rel-lista">' + rs.map(r => `<li><button data-rel="${r.id}"><span class="t">${r.from === l ? "" : esc(r.from) + " "}<em>—</em>${r.type}<em>→</em>${r.to === l && r.from !== l ? "" : " " + esc(r.to)}</span><span class="n">${fmt(r.n)}</span></button></li>`).join("") + "</ul>";
}
function aggancia() { scheda.querySelectorAll("[data-rel]").forEach(b => b.addEventListener("click", () => scegliRel(+b.dataset.rel))); scheda.querySelectorAll("[data-nodo]").forEach(b => b.addEventListener("click", () => scegliNodo(b.dataset.nodo))); }
function scegliNodo(l) {
  tuttiNodi.forEach(x => nodiEl[x].classList.toggle("acceso", x === l));
  const info = DATI.nodi[l], esce = REL.filter(r => r.from === l), entra = REL.filter(r => r.to === l && r.from !== l);
  const vicini = new Set([l, ...esce.map(r => r.to), ...entra.map(r => r.from)]);
  evidenzia(vicini, new Set([...esce, ...entra].map(r => r.id)));
  let h = `<div class="tipo">${ESTERNI[l] ? TT("Valore esterno", "External value") : TT("Tipo di nodo", "Node type")}</div><h2>${l}</h2><p class="desc">${DESC[l] || ""}</p>`;
  if (info) h += `<div class="meta"><span><b>${fmt(info.n)}</b> record</span><span>${info.prop.length} ${TT("proprietà", "properties")}</span></div><p class="fonti-nodo">${TT("Fonti", "Sources")}: ${[...new Set(info.fonti)].map(linkFonte).join(" · ")}</p>`;
  if (NOTE[l]) h += `<p class="nota">${NOTE[l]}</p>`;
  if (info) h += `<h3>${TT("Proprietà · quota valorizzata", "Properties · share filled")}</h3><ul class="prop">` + info.prop.map(([k, p, e, fs]) =>
    `<li><span class="k">${esc(k)}</span><span class="p">${p < 1 ? "<1" : p}%</span><span class="barra"><span style="width:${Math.max(p, 1)}%"></span></span>${e != null ? `<span class="es">${esc(e)}</span>` : ""}${daFonti(k, fs || [])}</li>`).join("") + "</ul>";
  h += `<h3>${TT("Relazioni in uscita", "Outgoing relationships")}</h3>${listaRel(esce, l)}<h3>${TT("Relazioni in entrata", "Incoming relationships")}</h3>${listaRel(entra, l)}`;
  scheda.innerHTML = h; aggancia();
}
function scegliRel(id) {
  const r = REL[id];
  tuttiNodi.forEach(x => nodiEl[x].classList.toggle("acceso", x === r.from || x === r.to));
  evidenzia(new Set([r.from, r.to]), new Set([id]));
  let h = `<div class="tipo">${r.perProp ? TT("Legame tramite proprietà", "Link through a property") : TT("Relazione", "Relationship")}${r.rif ? TT(" · riferimento", " · reference") : ""}</div><h2 style="font-family:var(--f-mono);font-size:22px">${r.type}</h2>
    <p class="desc">${SIGNIFICATO[r.type] || ""}</p>
    <div class="meta"><span><b>${fmt(r.n)}</b> ${TT("archi", "edges")}</span></div><p class="fonti-nodo">${TT("Fonti", "Sources")}: ${r.fonti.map(linkFonte).join(" · ")}</p>
    <ul class="rel-lista"><li><button data-nodo="${r.from}"><span class="t">${TT("da", "from")} <b>${r.from}</b></span><span class="n">${DATI.nodi[r.from] ? fmt(DATI.nodi[r.from].n) : ""}</span></button></li>
    <li><button data-nodo="${r.to}"><span class="t">${TT("a", "to")} <b>${r.to}</b></span><span class="n">${DATI.nodi[r.to] ? fmt(DATI.nodi[r.to].n) : TT("esterno", "external")}</span></button></li></ul>`;
  const NR = window.LANG === "en" ? {"RAPPORTEUR": "The origin is the written name (from_ref), not the person's uri.", "FROM": "The target is the group name written in the minutes.", "ON": "References to acts: ac19_1517, Senate bills, questions (aic…), documents.", "ABOUT": "References to acts: ddl:997, ac:2159, doc, aic, ag.", "TRANSMITTED": "Passage between houses: the reference is the number in the other house (S.872).", "SIGNS": "3,268 signatures with no linked person, outside this count.", "HAS_VIDEO": "4,321 video stretches with no linked speech, outside this count."} : { RAPPORTEUR: "L'origine è il nome scritto (from_ref), non l'uri della persona.", FROM: "Il destinatario è il nome del gruppo scritto nel resoconto.", ON: "Riferimenti ad atti: ac19_1517, ddl del Senato, interrogazioni (aic…), documenti.", ABOUT: "Riferimenti ad atti: ddl:997, ac:2159, doc, aic, ag.", TRANSMITTED: "Passaggio fra le Camere: il riferimento è il numero nell'altra Camera (S.872).", SIGNS: "3.268 firme senza persona collegata, fuori da questo conteggio.", HAS_VIDEO: "4.321 tratti video senza intervento collegato, fuori da questo conteggio." };
  if (r.perProp) h += `<p class="nota">${TT(`Nelle uscite è la proprietà <code>${r.type}</code> di ${r.from}, non un arco: ${fmt(r.n)} record la valorizzano. In Postgres diventa una colonna della tabella${r.type === "government" ? ", con chiave esterna verso government" : ""}.`, `In the outputs it is the <code>${r.type}</code> property of ${r.from}, not an edge: ${fmt(r.n)} records fill it. In Postgres it becomes a table column${r.type === "government" ? ", with a foreign key to government" : ""}.`)}</p>`;
  else if (NR[r.type]) h += `<p class="nota">${NR[r.type]}</p>`;
  if (!r.perProp) h += `<h3>${TT("Proprietà dell'arco", "Edge properties")}</h3>` + (r.prop.length ? `<ul class="prop">${r.prop.map(k => `<li><span class="k">${esc(k)}</span>${daFonti(k, (r.propFonti || {})[k] || [])}</li>`).join("")}</ul>` : `<p class="vuoto">${TT("Nessuna.", "None.")}</p>`);
  scheda.innerHTML = h; aggancia();
}
document.getElementById("g3-mostra-prop").addEventListener("change", ev => document.querySelector(".g3-mappa").classList.toggle("senza-prop", !ev.target.checked));
// tutto il grafo senza focus: nessun nodo acceso, la scheda dice come leggere la mappa
function tutto() {
  tuttiNodi.forEach(x => nodiEl[x].classList.remove("acceso")); evidenzia(null, null);
  const zone = ZONE.map(z => z[0]).filter(Boolean);
  scheda.innerHTML = `<div class="tipo">${TT("Tutto il grafo", "The whole graph")}</div><h2>${Object.keys(DATI.nodi).length} ${TT("tipi di nodo", "node types")}</h2>
    <p class="desc">${TT(`Ogni riquadro è un tipo di nodo, con il numero di record caricati. Le frecce sono le relazioni fra i tipi.${zone.length ? ` Le aree raggruppano ${zone.map(z => String(z).toLowerCase()).join(", ")}.` : ""}`, `Each box is a node type, with the number of records loaded. Arrows are the relationships between types.${zone.length ? ` The areas group ${zone.map(z => String(z).toLowerCase()).join(", ")}.` : ""}`)}</p>
    <p class="desc">${TT("Clicca un nodo per vedere le sue proprietà e da dove arrivano, oppure il nome di una relazione.", "Click a node to see its properties and where they come from, or the name of a relationship.")}</p>
    <h3>${TT("I tipi più grandi", "The largest types")}</h3><ul class="rel-lista">${Object.entries(DATI.nodi).sort((a, b) => b[1].n - a[1].n).slice(0, 8).map(([l, i]) => `<li><button data-nodo="${l}"><span class="t"><b>${l}</b></span><span class="n">${fmt(i.n)}</span></button></li>`).join("")}</ul>`;
  aggancia();
}
document.getElementById("g3-tutto").addEventListener("click", tutto);
svg.addEventListener("click", ev => { if (ev.target === svg) tutto(); });
{
  const usi = {}; Object.entries(DATI.nodi).forEach(([l, i]) => i.fonti.forEach(f => (usi[f] = usi[f] || []).push(l)));
  document.getElementById("g3-righe-fonti").innerHTML = Object.entries(FONTI).map(([f, x]) =>
    `<tr><td class="mono">${f}</td><td>${x.ente}</td><td class="sig">${esc(x.cosa)}</td><td class="sig">${x.url ? `<a href="${esc(x.url)}" target="_blank" rel="noopener">${esc(x.dove)}</a>` : esc(x.dove)}</td><td class="props">${(usi[f] || []).join(", ") || "—"}</td></tr>`).join("");
}
tutto();

